package com.example.rewards.controller;
import com.example.rewards.dto.CustomerRewardsResponse; import com.example.rewards.model.MonthlyReward; import com.example.rewards.model.Transaction; import com.example.rewards.service.RewardsService; import org.junit.jupiter.api.Test; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import java.math.BigDecimal; import java.time.*; import java.util.List; import static org.hamcrest.Matchers.hasSize; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class RewardsControllerUatTest {private final RewardsService s=mock(RewardsService.class); private final MockMvc mvc=MockMvcBuilders.standaloneSetup(new RewardsController(s)).build(); @Test void monthlyRewardsEndpoint() throws Exception{when(s.getRewardsForCustomer("C001")).thenReturn(new CustomerRewardsResponse("C001","Alice",List.of(new MonthlyReward("2026-01",115),new MonthlyReward("2026-02",250)),365));mvc.perform(get("/rewards/C001").accept(MediaType.APPLICATION_JSON)).andExpect(status().isOk()).andExpect(jsonPath("$.monthlyRewards",hasSize(2))).andExpect(jsonPath("$.monthlyRewards[0].rewardPoints").value(115)).andExpect(jsonPath("$.totalRewardPoints").value(365));} @Test void transactionRangeEndpoint() throws Exception{var tx=List.of(new Transaction("T1","C001","Alice",LocalDate.of(2026,1,5),new BigDecimal("120")),new Transaction("T3","C001","Alice",LocalDate.of(2026,2,10),new BigDecimal("200")));when(s.getTransactions("C001",YearMonth.of(2026,1),YearMonth.of(2026,2))).thenReturn(tx);mvc.perform(get("/transactions").param("customerId","C001").param("startMonth","2026-01").param("endMonth","2026-02")).andExpect(status().isOk()).andExpect(jsonPath("$",hasSize(2)));} @Test void invalidMonthIsBadRequest() throws Exception{mvc.perform(get("/transactions").param("startMonth","January-2026")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.message").value("startMonth must use YYYY-MM format"));}}
